// One item per feed entry comes in; keep the newest one we have not already
// rendered. Workflow static data remembers the last rendered guid — but ONLY
// on production executions (an active workflow). Manual test runs start empty.
// `Read blog feed` runs with alwaysOutputData + onError:continueRegularOutput,
// so a feed that parses to ZERO entries arrives here as one blank item and an
// unreachable feed as one error item. Without those two flags the RSS node
// emitted nothing, n8n skipped every downstream node, and the run finished
// "successful" with no output — the guard below could never fire.
const incoming = $input.all().map((i) => i.json || {});
const items = incoming.filter((it) => it && (it.title || it.link));
if (!items.length) {
  const failed = incoming.find((it) => it && (it.error || it.message));
  const detail = failed
    ? ' The feed request failed: ' + String((failed.error && (failed.error.message || failed.error)) || failed.message).slice(0, 200)
    : '';
  throw new Error('The feed returned no readable posts. Check feedUrl in Config — it must be an RSS or Atom feed URL, like https://blog.google/rss/.' + detail);
}

const ts = (it) => {
  const t = Date.parse(it.isoDate || it.pubDate || '');
  return Number.isFinite(t) ? t : null;
};
// Newest first when the feed provides dates. Feeds without dates keep feed
// order — virtually every feed lists newest first.
const dated = items.map((it, i) => ({ it, i, t: ts(it) }));
if (dated.some((d) => d.t !== null)) {
  dated.sort((a, b) => ((b.t == null ? -Infinity : b.t) - (a.t == null ? -Infinity : a.t)) || a.i - b.i);
}
const post = dated[0].it;

const link = String(post.link || '').trim();
const guid = String(post.guid || link || post.title).trim();

const store = $getWorkflowStaticData('global');
if (store.lastGuid && store.lastGuid === guid) {
  return [{ json: { found: false, reason: 'Newest post already rendered (guid unchanged since the last successful production run).', title: String(post.title || ''), guid } }];
}

// Feed body: full content when the feed carries it, else the snippet.
const raw = String(post['content:encoded'] || post.content || post.summary || post.contentSnippet || post.description || '');
const feedText = raw
  .replace(/\x3Cscript[\s\S]*?\x3C\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ').trim();

// n8n's Code-node sandbox has NO `URL` global (typeof URL === 'undefined'), so
// `new URL(link)` throws ReferenceError and this catch silently left the domain
// blank — every live render then fell back to the placeholder host. Parse the
// host off the string instead: works in n8n AND in plain node.
let domain = '';
const hostMatch = link.match(/^https?:\/\/([^\/?#]+)/i);
if (hostMatch) domain = hostMatch[1].replace(/^www\./, '').replace(/:\d+$/, '');

return [{
  json: {
    found: true,
    title: String(post.title || '').replace(/\s+/g, ' ').trim(),
    link,
    guid,
    domain,
    published: post.isoDate || post.pubDate || null,
    feedText,
  },
}];

// The newest post has already been rendered, so there is nothing to do until
// the blog publishes again. This is a normal, successful outcome — not an error.
const picked = $('Pick newest post').first().json;
return [{
  json: {
    rendered: false,
    reason: picked.reason || 'No new post.',
    newestPost: picked.title,
    nextStep: 'Run again after the next post is published. (Static data only persists on production executions, so manual test runs always see the newest post as new.)',
  },
}];

// Prefer the post's real page text over the feed excerpt: many feeds (including
// the default) only carry a one-line snippet, and a summary written from a
// snippet would force the model to invent the rest. The page fetch is
// best-effort — when it fails or the page is thin, the feed text is used and
// the prompt's no-invention rule keeps the script honest.
const cfg = $('Config').first().json;
const post = $('Pick newest post').first().json;
const res = $input.first().json || {};

const maxChars = Math.max(600, Number(cfg.maxPromptChars || 4000));
let pageText = '';
if (typeof res.data === 'string' && res.data.length > 200) {
  let html = res.data;
  const section = /<article[\s\S]*?<\/article>/i.exec(html) || /<main[\s\S]*?<\/main>/i.exec(html) || /<body[\s\S]*?<\/body>/i.exec(html);
  html = section ? section[0] : html;
  pageText = html
    .replace(/\x3Cscript[\s\S]*?\x3C\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ').trim();
}

// The page text wins only when it is meaningfully richer than the feed text.
const useable = pageText.length > Math.max(400, post.feedText.length * 1.5) ? pageText : post.feedText;
const articleSource = useable === pageText ? 'page' : 'feed';
const article = useable.slice(0, maxChars);

const targetWords = Math.round(Number(cfg.targetSeconds || 60) * 2.5);

const promptText = 'Blog post title: ' + post.title + '\n'
  + 'Blog domain: ' + post.domain + '\n'
  + 'Language: ' + (cfg.language || 'English') + '\n'
  + 'Target length: about ' + (cfg.targetSeconds || 60) + ' seconds of speech, roughly ' + targetWords + ' words in total\n'
  + '\nArticle text (may be partial):\n"""\n' + article + '\n"""\n'
  + '\nTurn this blog post into a short vertical summary video script. Rules:\n'
  + '1. Use ONLY facts that appear in the article text above. If the text is thin, stay general — NEVER invent numbers, names, dates or details that are not in it.\n'
  + '2. hook: one spoken sentence under fifteen words that opens with the most interesting idea of the post. No greeting, no "did you know".\n'
  + '3. points: three to five entries, in the order the article makes them. Each has:\n'
  + '   - text: ONE spoken sentence of fifteen to twenty five words summarising one concrete idea from the article.\n'
  + '   - label: an on-screen headline for that idea, EIGHT WORDS OR FEWER, no ending period.\n'
  + '   - visualQuery: two to four plain words naming concrete, filmable stock footage (an object, place or action - never an abstract idea).\n'
  + '4. cta: one spoken closing sentence inviting the viewer to read the full post on ' + (post.domain || 'the blog') + '.\n'
  + '5. Plain spoken words only: no emoji, markdown, quotes, parentheses or hashtags. Plain ASCII punctuation. Spell every number out as words ("nineteen", not "19") and avoid abbreviations.\n'
  + '6. title: a video title under sixty characters based on the post title.\n'
  + '7. musicTag: one of ambient, cinematic, inspiring, chill, calm, piano.\n'
  + '\nReturn exactly this JSON shape:\n'
  + '{\n  "title": "...",\n  "hook": "...",\n  "musicTag": "...",\n  "points": [{ "text": "...", "label": "...", "visualQuery": "..." }],\n  "cta": "..."\n}';

return [{ json: { promptText, articleSource, articleChars: article.length } }];

// Parses the writer's JSON, sanity-checks it, and builds the exact narration
// string that will be sent to TTS. Everything downstream reads this node.
const cfg = $('Config').first().json;
const post = $('Pick newest post').first().json;
const prep = $('Prepare prompt').first().json;
const res = $input.first().json;

const content = res && res.choices && res.choices[0] && res.choices[0].message ? res.choices[0].message.content : null;
if (!content) throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));

let script;
try { script = JSON.parse(content); } catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + content.slice(0, 400));
  script = JSON.parse(m[0]);
}

// Models slip curly quotes and dashes in even when told not to, and unusual
// characters make the voice stumble. Normalise to ASCII before anything counts
// words or reaches the synthesiser.
const toAscii = (s) => String(s)
  .replace(/[\u2018\u2019\u02BC]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2013\u2014]/g, '-')
  .replace(/\u2026/g, '...')
  .replace(/\s+/g, ' ')
  .trim();

const hook = toAscii(script.hook || '');
const cta = toAscii(script.cta || '');
if (!hook) throw new Error('The model returned no hook sentence.');
if (!cta) throw new Error('The model returned no cta sentence.');

let points = Array.isArray(script.points) ? script.points : [];
points = points
  .filter((p) => p && typeof p.text === 'string' && p.text.trim())
  .slice(0, 5) // free plans allow 5 video elements — one b-roll clip per point
  .map((p) => {
    const text = toAscii(p.text);
    let label = toAscii(p.label || '').replace(/[.!?]+$/, '');
    if (!label) label = text.split(' ').slice(0, 6).join(' ').replace(/[.!?,;:]+$/, '');
    const labelWords = label.split(' ');
    if (labelWords.length > 8) label = labelWords.slice(0, 8).join(' ');
    return { text, label, visualQuery: toAscii(p.visualQuery || post.title) };
  });
if (points.length < 3) throw new Error('The model returned only ' + points.length + ' usable points (need 3-5). Retry, or use a stronger model.');

const MUSIC_TAGS = ['ambient', 'cinematic', 'inspiring', 'chill', 'calm', 'piano'];
const musicTag = MUSIC_TAGS.includes(String(script.musicTag || '').toLowerCase()) ? String(script.musicTag).toLowerCase() : 'chill';

// One space between sentences. This exact string is what gets spoken, and the
// alignment that comes back is measured against it — which is what keeps
// captions and scene cuts frame-accurate.
const narration = [hook].concat(points.map((p) => p.text)).concat([cta]).join(' ');
const targetWords = Math.round(Number(cfg.targetSeconds || 60) * 2.5);
const wordCount = narration.split(/\s+/).filter(Boolean).length;
// A legitimate 3-point summary can sit near half the target, so the guard is
// 50% — it exists to stop a one-line script from reaching a paid render.
if (wordCount < targetWords * 0.5) {
  throw new Error('The script is only ' + wordCount + ' words for a ' + cfg.targetSeconds + 's video (expected around ' + targetWords + '). Retry, or use a stronger model.');
}

return [{
  json: {
    title: String(script.title || post.title).slice(0, 100),
    hook,
    points,
    cta,
    narration,
    musicTag,
    wordCount,
    targetWords,
    articleSource: prep.articleSource,
    post: { title: post.title, link: post.link, domain: post.domain, published: post.published, guid: post.guid },
  },
}];

// One item per point so the stock search below runs once per point.
const script = $input.first().json;
return script.points.map((p, index) => ({ json: { index, visualQuery: p.visualQuery, label: p.label } }));

// Picks one b-roll clip per point from Zvid's stock library.
// Portrait clips win because the canvas is 1080x1920 — a landscape clip still
// works via resize:"cover", it is just cropped harder.
const cfg = $('Config').first().json;
const script = $('Parse script').first().json;
const responses = $input.all();
const approxSceneSeconds = Number(cfg.targetSeconds || 60) / Math.max(1, script.points.length + 2);

function pick(items, needSeconds) {
  const usable = (items || []).filter((it) => it && it.src);
  if (!usable.length) return null;
  return usable
    .map((it) => {
      const portrait = Number(it.height) > Number(it.width);
      const longEnough = Number(it.duration || 0) >= needSeconds;
      return {
        it,
        score: (portrait ? 2 : 0) + (longEnough ? 1 : 0) + Math.min(1, Number(it.duration || 0) / 30),
      };
    })
    .sort((a, b) => b.score - a.score)[0].it;
}

const sceneMedia = script.points.map((_, i) => {
  const body = responses[i] && responses[i].json ? responses[i].json : {};
  const chosen = pick(body.items, approxSceneSeconds);
  if (!chosen) return null;
  return {
    kind: chosen.kind || 'video',
    src: chosen.src,
    duration: Number(chosen.duration) || null,
    width: Number(chosen.width) || null,
    height: Number(chosen.height) || null,
    credit: chosen.credit || null,
  };
});

// Unlike a pure b-roll format, a missing clip never fails this workflow: that
// point renders as a designed brand slide instead (big point label, progress
// rail, animated light sweep).
const missing = sceneMedia.filter((m) => !m).length;
return [{ json: { sceneMedia, missing } }];

// The music catalogue is tag-matched and occasionally returns nothing for a tag
// that worked a minute ago, so ask for the writer's tag plus two broad
// fallbacks. One item per query -> the search node runs once per tag.
const tag = $('Parse script').first().json.musicTag;
const queries = [...new Set([tag, 'chill', 'ambient'])];
return queries.map((query) => ({ json: { query } }));

// Rank the music candidates. Long tracks mean big files, and the renderer
// rejects any asset over the plan's audio size cap — a 6.3 MB track fails the
// WHOLE render, so a nice-to-have music bed must never be able to do that.
// Shortest-but-long-enough wins; the next node probes the real byte size.
const cfg = $('Config').first().json;
const maxSeconds = Number(cfg.maxMusicSeconds == null ? 200 : cfg.maxMusicSeconds);

const seen = new Set();
const all = [];
for (const r of $input.all()) {
  for (const m of r.json.items || []) {
    if (!m || !m.src) continue;
    const key = m.id || m.src;
    if (seen.has(key)) continue;
    seen.add(key);
    all.push(m);
  }
}

const sized = all
  .filter((m) => { const d = Number(m.duration) || 0; return d >= 45 && d <= maxSeconds; })
  .sort((a, b) => (Number(a.duration) || 0) - (Number(b.duration) || 0));

const pool = (sized.length ? sized : all).slice(0, 4);
if (!pool.length) {
  // Nothing to probe — send one item the probe can hit harmlessly.
  return [{ json: { candidate: null, probeUrl: cfg.apiUrl } }];
}
return pool.map((candidate) => ({ json: { candidate, probeUrl: candidate.src } }));

// Keep the first candidate that is actually downloadable and within the size
// cap, then collapse to ONE item — otherwise the voiceover step downstream
// would run once per candidate. No usable track just means no music bed; it
// must never fail the run.
const cfg = $('Config').first().json;
const limit = Number(cfg.maxMusicBytes == null ? 5242880 : cfg.maxMusicBytes);
const shortlist = $('Shortlist music').all().map((i) => i.json);
const probes = $input.all();

let music = null;
const rejected = [];
for (let i = 0; i < probes.length; i += 1) {
  const candidate = shortlist[i] && shortlist[i].candidate;
  if (!candidate) continue;
  const p = probes[i] ? probes[i].json : {};
  const status = Number(p.statusCode);
  const headers = p.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);

  if (status !== 200) { rejected.push(candidate.id + ': HTTP ' + (status || '?')); continue; }
  if (bytes && bytes > limit) { rejected.push(candidate.id + ': ' + bytes + ' bytes > ' + limit); continue; }
  music = candidate;
  break;
}

return [{ json: { music, checked: probes.length, rejected } }];

// Turns one ElevenLabs "with-timestamps" response into (a) an mp3 binary ready
// for upload and (b) word timings.
//
// The alignment comes from the synthesiser itself, so the timings ARE the audio
// — there is no separate transcription step to disagree with, and nothing that
// can drift. That is the whole reason this endpoint is used instead of plain
// text-to-speech.
const res = $input.first().json;

if (!res || !res.audio_base64) {
  throw new Error(
    'ElevenLabs returned no audio. Check the xi-api-key credential, the voiceId, and your character quota. Response: ' +
      JSON.stringify(res).slice(0, 300)
  );
}

const a = res.alignment || res.normalized_alignment;
if (!a || !Array.isArray(a.characters)) {
  throw new Error('ElevenLabs returned audio but no alignment — make sure the URL ends in /with-timestamps.');
}

const chars = a.characters;
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];

// Alignment is per CHARACTER; group runs of non-whitespace into words.
const words = [];
let cur = null;
for (let i = 0; i < chars.length; i += 1) {
  const ch = chars[i];
  if (/\s/.test(ch)) {
    if (cur) { words.push(cur); cur = null; }
    continue;
  }
  if (!cur) cur = { text: ch, start: Number(starts[i]), end: Number(ends[i]) };
  else { cur.text += ch; cur.end = Number(ends[i]); }
}
if (cur) words.push(cur);

if (!words.length) throw new Error('Alignment contained no words.');

const duration = Number(ends[ends.length - 1]) || words[words.length - 1].end;

return [{
  json: { words, duration, wordCount: words.length },
  // n8n binary payloads carry base64 in `data`; naming it matters because Zvid
  // derives the media kind from the MIME type on upload.
  binary: {
    data: {
      data: res.audio_base64,
      mimeType: 'audio/mpeg',
      fileName: 'voiceover.mp3',
      fileExtension: 'mp3',
    },
  },
}];

// Assembles the Zvid project JSON: branded intro card, one point scene per
// summary point (b-roll or brand panel + accent-bar point card), outro CTA
// card, word-timed karaoke captions, voiceover and music bed.
const cfg = $('Config').first().json;
const script = $('Parse script').first().json;
const sceneMedia = $('Pick scene clip').first().json.sceneMedia;
const music = $('Pick music').first().json.music || null;
const upload = $('Upload voiceover').first().json.upload;
const timings = $('Voice + timings').first().json;

if (!upload || !upload.url) {
  throw new Error('The voiceover upload returned no URL: ' + JSON.stringify($('Upload voiceover').first().json).slice(0, 300));
}

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const round = (n) => Math.round(n * 100) / 100;
const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ---- brand ---------------------------------------------------------------
const bg = String(cfg.brandColor || '#0F1626').trim();
const accent = String(cfg.brandAccent || '#FFB454').trim();
const textColor = String(cfg.textColor || '#FFFFFF').trim();
const muted = String(cfg.mutedTextColor || '#9AA7BD').trim();
const headlineFont = String(cfg.headlineFont || 'Archivo').trim();
const uiFont = String(cfg.uiFont || 'Space Grotesk').trim();
const brandName = String(cfg.brandName || 'The Blog').replace(/\s+/g, ' ').trim();

// Lighten/alpha helpers so every panel and scrim follows brandColor instead of
// hardcoding a second palette.
const hexRgb = (hex) => {
  const m = /^#?([0-9a-fA-F]{6})$/.exec(String(hex).trim());
  const n = m ? parseInt(m[1], 16) : 0x0f1626;
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
const lighten = (hex, amt) => {
  const [r, g, b] = hexRgb(hex);
  const ch = (v) => clamp(Math.round(v + amt), 0, 255).toString(16).padStart(2, '0');
  return '#' + ch(r) + ch(g) + ch(b);
};
const rgba = (hex, a) => {
  const [r, g, b] = hexRgb(hex);
  return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
};
const bgLift = lighten(bg, 22);

// ---- narration timing (same machinery as the faceless-shorts template) ---
const words = (Array.isArray(timings.words) ? timings.words : [])
  .map((w) => ({ text: String(w.text == null ? '' : w.text).trim(), start: Number(w.start), end: Number(w.end) }))
  .filter((w) => w.text && Number.isFinite(w.start) && Number.isFinite(w.end));

const narrationEnd = words.length ? words[words.length - 1].end : Number(timings.duration) || 45;
const audioDuration = Math.max(Number(timings.duration) || 0, narrationEnd);

// The alignment groups characters by WHITESPACE, so the script is counted the
// same way: whitespace-delimited tokens that contain at least one letter or
// digit ("on-device" is one word on both sides, unlike a class-based split).
const countWords = (s) =>
  String(s || '').trim().split(/\s+/).filter((t) => /[\p{L}\p{N}]/u.test(t)).length;

// Units: hook -> intro scene, each point -> its own scene, cta -> outro scene.
const points = script.points;
const units = [script.hook].concat(points.map((p) => p.text)).concat([script.cta]);
const perUnit = units.map((u) => countWords(u));
const totalScripted = perUnit.reduce((a, b) => a + b, 0);

// Walking the timed word stream by per-unit word count puts every cut on a
// sentence boundary. If tokenisation drifts (digits, abbreviations), fall back
// to a proportional split so the render can never desync.
const drift = totalScripted ? Math.abs(words.length - totalScripted) / totalScripted : 1;
const useWordMap = words.length > 0 && drift <= 0.2;

const spans = [];
if (useWordMap) {
  let cursor = 0;
  for (let i = 0; i < perUnit.length; i += 1) {
    const start = cursor === 0 ? 0 : words[cursor - 1].end;
    cursor = Math.min(cursor + perUnit[i], words.length);
    const last = words[cursor - 1];
    spans.push({ start, end: i === perUnit.length - 1 ? audioDuration : last ? last.end : audioDuration });
  }
} else {
  const weightTotal = totalScripted || perUnit.length;
  let t = 0;
  for (let i = 0; i < perUnit.length; i += 1) {
    const start = t;
    t = i === perUnit.length - 1 ? audioDuration : t + ((perUnit[i] || 1) / weightTotal) * audioDuration;
    spans.push({ start, end: t });
  }
}
spans[spans.length - 1].end += Number(cfg.tailSeconds == null ? 0.4 : cfg.tailSeconds);

const transition = cfg.sceneTransition || null;
const tDur = transition ? Number(cfg.transitionSeconds == null ? 0.4 : cfg.transitionSeconds) : 0;
const minScene = Math.max(1.6, tDur * 3);
const visibleOf = (span) => Math.max(minScene, round(span.end - span.start));

// ---- adaptive type -------------------------------------------------------
// Greedy word-wrap estimate (Archivo 800 averages ~0.55em per glyph) so the
// intro chip can sit below however many lines the title takes.
const wrapLines = (text, fontPx, boxPx, avgEm) => {
  const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
  let lines = 1;
  let used = 0;
  for (const w of String(text).split(' ')) {
    const need = used === 0 ? w.length : used + 1 + w.length;
    if (need <= perLine) { used = need; continue; }
    lines += 1;
    used = Math.min(w.length, perLine);
  }
  return lines;
};

// The intro shows the REAL post title (the LLM title is only video metadata).
let postTitle = String(script.post.title || '').replace(/\s+/g, ' ').trim();
if (postTitle.length > 110) {
  postTitle = postTitle.slice(0, 109).replace(/\s+\S*$/, '') + '…';
}
const titleSize = postTitle.length <= 45 ? 62 : postTitle.length <= 65 ? 54 : postTitle.length <= 85 ? 47 : 41;
const titleLines = wrapLines(postTitle, titleSize, 900, 0.55);
const titleY = 640;
const chipY = Math.round(titleY + 96 + titleLines * titleSize * 1.14 + 56);

// Dateline: the post date when the feed provides one, otherwise the domain.
// A feed entry can carry neither (no date, no absolute link), and both places
// that print these fields must survive that: the dateline is dropped entirely
// rather than rendering an empty line.
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const pubTs = script.post.published ? Date.parse(script.post.published) : NaN;
const dateLine = Number.isFinite(pubTs)
  ? (() => { const d = new Date(pubTs); return MONTHS[d.getUTCMonth()] + ' ' + d.getUTCDate() + ', ' + d.getUTCFullYear(); })()
  : String(script.post.domain || '').trim();

// ---- scenes --------------------------------------------------------------
const scenes = [];

// Slow radial light drift for the two card scenes (intro and outro), which
// would otherwise freeze once their entrance animations finish. Only
// background-position animates: it never changes the element's box, so the
// frame capture can never grow past the canvas. The keyframes start and end on
// the same position, so a loop shorter than the scene repeats without a seam.
const glowCss =
  '.btvg{position:relative;width:1080px;height:1920px;overflow:hidden}' +
  '.btvg i{position:absolute;display:block;left:0;top:0;width:1080px;height:1920px;background-repeat:no-repeat;' +
  'background-size:1500px 1500px;background-image:radial-gradient(circle,' + rgba(bgLift, 0.8) + ' 0%,rgba(0,0,0,0) 66%);' +
  'animation:btvGlow 8s ease-in-out infinite}' +
  '@keyframes btvGlow{0%{background-position:-240px 40px}33%{background-position:540px 640px}66%{background-position:-80px 1060px}100%{background-position:-240px 40px}}';
const glowVisual = (dur, track) => ({
  type: 'TEXT', x: 540, y: 960, anchor: 'center-center', track, enterBegin: 0, exitEnd: dur,
  style: { fontFamily: uiFont, color: textColor },
  html: "<div class='btvg'><i></i></div>",
  customCode: { animationDuration: Math.min(8, dur), css: glowCss },
});

// Scene 1: branded intro card.
const introVisible = visibleOf(spans[0]);
const introDur = round(introVisible + tDur);
// A dim version of the point-progress rail used on the point scenes: it tells
// the viewer up front how many ideas are coming and ties the intro to them.
const introRail = points
  .map((_, n) => "<span style='width:54px; height:5px; border-radius:3px; background:" + rgba(accent, n === 0 ? 0.55 : 0.2) + ";'></span>")
  .join('');
scenes.push({
  id: 'intro',
  duration: introDur,
  backgroundColor: bg,
  ...(transition ? { transition, transitionDuration: tDur } : {}),
  visuals: [
    {
      type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: introDur,
      svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='btvIntro' cx='0.28' cy='0.3' r='1.05'><stop offset='0' stop-color='" + bgLift + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient><pattern id='btvDots' width='44' height='44' patternUnits='userSpaceOnUse'><circle cx='3' cy='3' r='3' fill='" + rgba(accent, 0.16) + "'/></pattern></defs><rect width='1080' height='1920' fill='url(#btvIntro)'/><rect x='680' y='150' width='310' height='310' fill='url(#btvDots)'/><rect x='90' y='560' width='150' height='10' rx='5' fill='" + accent + "'/><path d='M90 1780 H430' stroke='" + rgba(accent, 0.35) + "' stroke-width='1.5'/></svg>",
    },
    glowVisual(introDur, 1),
    {
      type: 'TEXT', x: 90, y: 620, anchor: 'top-left', track: 2, enterBegin: 0.15, enterEnd: 0.55, enterAnimation: 'smoothright', exitEnd: introDur,
      style: { fontFamily: uiFont, color: accent },
      html: "<div style='color:" + accent + "; font-size:30px; font-weight:700; letter-spacing:8px;'>NEW ON THE BLOG</div>" + (dateLine ? "<div style='margin-top:12px; color:" + muted + "; font-size:26px; font-weight:600; letter-spacing:4px;'>" + escapeHtml(dateLine) + '</div>' : ''),
    },
    {
      type: 'TEXT', x: 90, y: titleY + 96, width: 900, anchor: 'top-left', track: 3, enterBegin: 0.4, enterEnd: 0.9, enterAnimation: 'smoothup', exitEnd: introDur,
      style: { fontFamily: headlineFont, color: textColor },
      html: "<div style='color:" + textColor + '; font-size:' + titleSize + "px; line-height:1.14; font-weight:800; letter-spacing:-1px; text-wrap:balance;'>" + escapeHtml(postTitle) + '</div>',
    },
    {
      type: 'TEXT', x: 90, y: chipY, anchor: 'top-left', track: 4, enterBegin: 0.85, enterEnd: 1.25, enterAnimation: 'fade', exitEnd: introDur,
      style: { fontFamily: uiFont, color: accent },
      html: "<span style='display:inline-block; background:" + rgba(accent, 0.14) + '; border:1.5px solid ' + rgba(accent, 0.5) + '; color:' + accent + "; border-radius:999px; padding:12px 28px; font-size:26px; font-weight:700; letter-spacing:3px;'>&#9679;&nbsp; " + escapeHtml(brandName.toUpperCase()) + '</span>',
    },
    {
      type: 'TEXT', x: 90, y: chipY + 108, width: 900, anchor: 'top-left', track: 4, enterBegin: 1.15, enterEnd: 1.6, enterAnimation: 'wiperight', exitEnd: introDur,
      style: { fontFamily: uiFont, color: muted },
      html: "<div style='display:flex; align-items:center; gap:12px;'>" + introRail + "<span style='margin-left:12px; color:" + muted + "; font-size:22px; font-weight:700; letter-spacing:5px;'>" + points.length + " POINTS</span></div>",
    },
  ],
});

// Point scenes: b-roll (or a designed brand slide) + accent-bar point card.
const cardBg = rgba(bg, 0.9);

// Motion layer for the no-b-roll slide. Only background-position and opacity
// animate: neither changes an element's box, so the frame capture never has to
// grow past the canvas. Every period divides the 8 s loop, so a scene longer
// than the loop repeats it without a visible seam.
const slideCss =
  '.btvw{position:relative;width:1080px;height:1920px;overflow:hidden}' +
  '.btvw i{position:absolute;display:block;left:0;top:0;width:1080px;height:1920px;background-repeat:no-repeat}' +
  '.btvw .lt{background-size:1500px 1500px;background-image:radial-gradient(circle,' + rgba(bgLift, 0.85) + ' 0%,rgba(0,0,0,0) 68%);animation:btvLight 8s ease-in-out infinite}' +
  '.btvw .bm{background-size:250% 100%;background-image:linear-gradient(104deg,rgba(0,0,0,0) 40%,' + rgba(accent, 0.22) + ' 50%,rgba(0,0,0,0) 60%);animation:btvBeam 8s linear infinite}' +
  '.btvw .rg{left:60px;top:210px;width:380px;height:380px;border-radius:50%;border:2px solid ' + rgba(accent, 0.16) + ';animation:btvPulse 4s ease-in-out infinite}' +
  '.btvw .rg2{left:155px;top:305px;width:190px;height:190px;border-radius:50%;border:2px solid ' + rgba(accent, 0.26) + ';animation:btvPulse 4s ease-in-out infinite;animation-delay:-2s}' +
  '@keyframes btvLight{0%{background-position:-260px 60px}25%{background-position:420px -40px}50%{background-position:820px 520px}75%{background-position:140px 760px}100%{background-position:-260px 60px}}' +
  '@keyframes btvBeam{0%{background-position:0% 0}100%{background-position:100% 0}}' +
  '@keyframes btvPulse{0%{opacity:0.3}50%{opacity:0.95}100%{opacity:0.3}}';

points.forEach((point, i) => {
  const span = spans[i + 1];
  const visible = visibleOf(span);
  const dur = round(visible + tDur);
  const media = sceneMedia[i] || null;
  const visuals = [];
  const label = point.label;
  const num = String(i + 1).padStart(2, '0');

  if (media && media.kind === 'video') {
    // videoEnd is measured in SOURCE time: a clip played at speed s covers
    // visible * s seconds of source. Slowing a short clip beats a freeze.
    const speed = media.duration && media.duration < visible
      ? clamp(round(media.duration / visible), 0.5, 1)
      : 1;
    const sourceWindow = round(visible * speed);
    visuals.push({
      type: 'VIDEO',
      src: media.src,
      resize: 'cover',
      position: 'center-center',
      anchor: 'center-center',
      volume: 0,
      videoBegin: 0,
      videoEnd: media.duration ? Math.min(media.duration, sourceWindow) : sourceWindow,
      ...(speed !== 1 ? { speed } : {}),
      zoom: { depth: Number(cfg.kenBurnsDepth == null ? 1.12 : cfg.kenBurnsDepth) },
    });
    visuals.push({
      type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: dur,
      svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='btvScrim" + i + "' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='" + bg + "' stop-opacity='0.55'/><stop offset='0.4' stop-color='" + bg + "' stop-opacity='0.16'/><stop offset='1' stop-color='" + bg + "' stop-opacity='0.88'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#btvScrim" + i + ")'/></svg>",
    });
    // Point card: kicker + short headline, held over the footage.
    const labelSize = label.length <= 34 ? 40 : label.length <= 52 ? 36 : 32;
    visuals.push({
      type: 'TEXT', x: 90, y: 1120, width: 900, anchor: 'top-left', track: 2, enterBegin: 0.25, enterEnd: 0.65, enterAnimation: 'smoothleft', exitEnd: dur,
      style: { fontFamily: headlineFont, color: textColor },
      html: "<div style='display:inline-block; background:" + cardBg + '; border-left:6px solid ' + accent + "; border-radius:16px; padding:24px 34px; max-width:860px;'><div style='color:" + accent + "; font-size:25px; font-weight:800; letter-spacing:5px;'>POINT " + num + "</div><div style='margin-top:8px; color:" + textColor + '; font-size:' + labelSize + "px; line-height:1.22; font-weight:800; text-wrap:balance;'>" + escapeHtml(label) + '</div></div>',
    });
  } else {
    // No usable b-roll for this point. The scene is not a spare panel with the
    // card floating on it: it becomes its own layout — the point label carried
    // at headline size, a progress rail marking which point this is, brand
    // geometry, and a slow light sweep so the frame keeps moving like the
    // b-roll scenes do.
    visuals.push({
      type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: dur,
      svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='btvPanel" + i + "' cx='0.72' cy='0.24' r='1.1'><stop offset='0' stop-color='" + bgLift + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient><pattern id='btvPanelDots" + i + "' width='44' height='44' patternUnits='userSpaceOnUse'><circle cx='3' cy='3' r='3' fill='" + rgba(accent, 0.16) + "'/></pattern></defs><rect width='1080' height='1920' fill='url(#btvPanel" + i + ")'/><rect x='680' y='150' width='310' height='310' fill='url(#btvPanelDots" + i + ")'/><path d='M90 1780 H430' stroke='" + rgba(accent, 0.35) + "' stroke-width='1.5'/></svg>",
    });
    visuals.push({
      type: 'TEXT', x: 540, y: 960, anchor: 'center-center', track: 1, enterBegin: 0, exitEnd: dur,
      style: { fontFamily: uiFont, color: textColor },
      html: "<div class='btvw'><i class='lt'></i><i class='bm'></i><i class='rg'></i><i class='rg2'></i></div>",
      customCode: { animationDuration: Math.min(8, dur), css: slideCss },
    });

    // The label is the whole slide here, so it gets headline sizing and the
    // block is centred on the canvas rather than pinned to the card slot.
    const slideSize = label.length <= 30 ? 68 : label.length <= 46 ? 60 : label.length <= 68 ? 52 : 44;
    const slideLines = wrapLines(label, slideSize, 856, 0.55);
    const blockHeight = Math.round(44 + slideLines * slideSize * 1.14);
    const blockY = Math.round(980 - blockHeight / 2);
    visuals.push({
      type: 'TEXT', x: 90, y: blockY, width: 900, anchor: 'top-left', track: 2, enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'smoothleft', exitEnd: dur,
      style: { fontFamily: headlineFont, color: textColor },
      html: "<div style='display:inline-block; border-left:8px solid " + accent + "; padding-left:34px; max-width:856px;'><div style='color:" + accent + "; font-size:25px; font-weight:800; letter-spacing:5px;'>POINT " + num + "</div><div style='margin-top:14px; color:" + textColor + '; font-size:' + slideSize + "px; line-height:1.14; font-weight:800; letter-spacing:-0.5px; text-wrap:balance;'>" + escapeHtml(label) + '</div></div>',
    });
    const railSegments = points
      .map((_, n) => "<span style='flex:1; height:6px; border-radius:3px; background:" + (n === i ? accent : rgba(accent, 0.18)) + ";'></span>")
      .join('');
    visuals.push({
      type: 'TEXT', x: 90, y: blockY + blockHeight + 64, width: 900, anchor: 'top-left', track: 3, enterBegin: 0.7, enterEnd: 1.15, enterAnimation: 'wiperight', exitEnd: dur,
      style: { fontFamily: uiFont, color: accent },
      html: "<div style='display:flex; gap:12px;'>" + railSegments + '</div>',
    });
  }

  scenes.push({
    id: 'point-' + (i + 1),
    duration: dur,
    backgroundColor: bg,
    ...(transition ? { transition, transitionDuration: tDur } : {}),
    visuals,
  });
});

// Outro: CTA + the blog's domain.
const ctaSpan = spans[spans.length - 1];
const outroDur = visibleOf(ctaSpan);
const ctaText = String(cfg.ctaText || 'Read the full post').replace(/\s+/g, ' ').trim();
const ctaSize = ctaText.length <= 26 ? 64 : ctaText.length <= 40 ? 54 : 46;
// The CTA is centred inside a FIXED-height band instead of being measured, so
// the pill below it always sits the same distance away. Estimating the line
// count here put the pill ~60 px low whenever the estimate over-predicted by
// one line, which is exactly what a two-line-looking one-line CTA does.
const CTA_BAND = 200;
const ctaTop = 880;
const pillY = ctaTop + CTA_BAND + 40;
// The pill prints the blog's domain, but a feed entry with no absolute link
// leaves `domain` empty — and a filled accent pill with no text is just a blank
// lozenge on screen. Fall back to the brand name (the same fallback the prompt
// builder already uses for the spoken CTA) and drop the brand line underneath
// when it would only repeat the pill.
const pillText = String(script.post.domain || '').trim() || brandName;
const brandLineHtml = pillText.toLowerCase() === brandName.toLowerCase()
  ? ''
  : "<div style='margin-top:18px; text-align:center; color:" + muted + "; font-size:24px; font-weight:600; letter-spacing:5px;'>" + escapeHtml(brandName.toUpperCase()) + '</div>';
scenes.push({
  id: 'outro',
  duration: outroDur,
  backgroundColor: bg,
  visuals: [
    {
      type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: outroDur,
      svg: "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='btvEnd' cx='0.5' cy='0.38' r='0.95'><stop offset='0' stop-color='" + bgLift + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#btvEnd)'/><circle cx='540' cy='680' r='110' fill='none' stroke='" + rgba(accent, 0.55) + "' stroke-width='2.5'/><path d='M492 680 H580 M548 644 L588 680 L548 716' fill='none' stroke='" + accent + "' stroke-width='11' stroke-linecap='round' stroke-linejoin='round'/></svg>",
    },
    glowVisual(outroDur, 1),
    {
      type: 'TEXT', x: 540, y: ctaTop, width: 920, anchor: 'top-center', track: 2, enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: outroDur,
      style: { fontFamily: headlineFont, color: textColor },
      html: "<div style='height:" + CTA_BAND + "px; display:flex; align-items:center; justify-content:center;'><div style='text-align:center; color:" + textColor + '; font-size:' + ctaSize + "px; line-height:1.15; font-weight:800; letter-spacing:-1px; text-wrap:balance;'>" + escapeHtml(ctaText) + '</div></div>',
    },
    {
      type: 'TEXT', x: 540, y: pillY, anchor: 'top-center', track: 3, enterBegin: 0.7, enterEnd: 1.1, enterAnimation: 'circleopen', exitEnd: outroDur,
      style: { fontFamily: uiFont, color: accent },
      html: "<div style='display:inline-block; background:" + accent + '; color:' + bg + "; border-radius:999px; padding:22px 54px; font-size:32px; font-weight:800;'>" + escapeHtml(pillText) + '</div>' + brandLineHtml,
    },
  ],
});

const totalDuration = round(
  scenes.reduce((sum, s) => sum + s.duration, 0) - tDur * Math.max(0, scenes.length - 1)
);

// ---- captions ------------------------------------------------------------
// Free plans cap a project at 200 caption cues. At the default three words a
// cue a 60-second script is nowhere near it, but a raised `targetSeconds`
// breaches the cue cap long before it breaches the duration cap — so widen the
// cue rather than dropping the tail. Every spoken word still gets captioned.
// `maxWordsPerLine` is capped at 20 by the project schema, so clamp what the
// user asked for instead of letting a typo (captionWordsPerCue: 30) fail
// validation on every run.
const MAX_CAPTION_CUES = 200;
const MAX_WORDS_PER_LINE = 20;
const rawPerCue = Number(cfg.captionWordsPerCue == null ? 3 : cfg.captionWordsPerCue);
const requestedPerCue = Math.min(MAX_WORDS_PER_LINE, Math.max(1, Number.isFinite(rawPerCue) ? Math.round(rawPerCue) : 3));
const perCue = Math.max(requestedPerCue, Math.ceil(words.length / MAX_CAPTION_CUES));
const captions = [];
for (let i = 0; i < words.length; i += perCue) {
  const chunk = words.slice(i, i + perCue);
  captions.push({
    start: chunk[0].start,
    end: chunk[chunk.length - 1].end,
    text: chunk.map((w) => w.text).join(' '),
    words: chunk.map((w) => ({ start: w.start, end: w.end, text: w.text })),
  });
}

// In box modes ("highlight") the chip behind the spoken word is drawn first
// and the outline on top of it, so box modes get a thin outline plus padding;
// every other mode keeps the heavy outline that stays readable on any b-roll.
const BOX_MODES = ['highlight'];
const animation = cfg.captionAnimation || 'karaoke';
const usesBox = BOX_MODES.includes(animation);
const strokeWidth = Math.max(0, Number(cfg.captionStrokeWidth == null ? 6 : cfg.captionStrokeWidth));

const subtitle = {
  captions,
  animation,
  activeWord: usesBox
    ? { color: cfg.captionActiveColor || bg, background: accent }
    : { color: accent },
  font: {
    family: uiFont,
    size: Number(cfg.captionSize == null ? 54 : cfg.captionSize),
    color: '#ffffff',
    bold: true,
    transform: 'uppercase',
  },
  stroke: { color: '#000000', width: usesBox ? Math.min(strokeWidth, 2) : strokeWidth },
  ...(usesBox ? { background: { padding: 14 } } : {}),
  position: 'bottom',
  margin: { x: 90, y: 300 },
  maxWordsPerLine: Math.min(MAX_WORDS_PER_LINE, perCue),
};

// ---- global watermark + audio -------------------------------------------
// A dark pill keeps the watermark readable over ANY footage — plain white
// text washed out on bright clips (x/y because a `position` preset would
// ignore them).
const visuals = [{
  type: 'TEXT',
  x: 540,
  y: 84,
  anchor: 'top-center',
  track: 5,
  opacity: 0.9,
  style: { fontFamily: uiFont, color: '#ffffff' },
  html: "<div style='display:inline-block; background:" + rgba(bg, 0.55) + "; border:1px solid rgba(255,255,255,0.18); border-radius:999px; padding:10px 28px; color:#ffffff; font-size:25px; font-weight:700; letter-spacing:4px;'>" + escapeHtml(brandName) + '</div>',
}];

// NOTE: no `track` on audios — the render API rejects audios[].track.
const audios = [{ src: upload.url, volume: 1, enter: 0 }];
if (music) {
  audios.push({ src: music.src, volume: Number(cfg.musicVolume == null ? 0.1 : cfg.musicVolume), enter: 0, exit: totalDuration });
}

// The render API only allows letters, digits, spaces, _ and - in `name`.
const name = ('blog-video-' + script.post.title).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'blog-video';

const payload = {
  name,
  resolution: cfg.resolution || 'instagram-reel',
  frameRate: Number(cfg.frameRate == null ? 30 : cfg.frameRate),
  backgroundColor: bg,
  outputFormat: 'mp4',
  scenes,
  visuals,
  audios,
  subtitle,
};

return [{
  json: {
    payload,
    meta: {
      postTitle: script.post.title,
      videoTitle: script.title,
      domain: script.post.domain,
      link: script.post.link,
      guid: script.post.guid,
      published: script.post.published || null,
      articleSource: script.articleSource,
      pointCount: points.length,
      narrationSeconds: round(audioDuration),
      totalDuration,
      sceneCount: scenes.length,
      videoClips: sceneMedia.filter((m) => m && m.kind === 'video').length,
      captionCount: captions.length,
      captionWordsPerCue: perCue,
      cutsAlignedToSpeech: useWordMap,
      musicTrack: music ? music.description || music.src : null,
    },
  },
}];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. The last-guid
// memory is NOT updated on a dry run, so the next real run renders this post.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    postTitle: d.meta.postTitle,
    videoTitle: d.meta.videoTitle,
    domain: d.meta.domain,
    points: d.meta.pointCount,
    articleSource: d.meta.articleSource,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalDuration,
    narrationSeconds: d.meta.narrationSeconds,
    cutsAlignedToSpeech: d.meta.cutsAlignedToSpeech,
    captions: d.meta.captionCount,
    musicTrack: d.meta.musicTrack,
    warnings: d.warnings,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. The finished post's guid is remembered HERE —
// only after a successful render — so a failed render is retried on the next
// run, and dry runs never consume the post. (Static data only persists on
// production executions; manual test runs re-render the newest post.)
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const store = $getWorkflowStaticData('global');
store.lastGuid = build.meta.guid;

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    postTitle: build.meta.postTitle,
    videoTitle: build.meta.videoTitle,
    postLink: build.meta.link,
